// Generated by the Salvo compiler: sequence helpers.

/// `map(list, f)`: every element, in order.
pub fn salvo_map<T, U, F: FnMut(&T) -> U>(xs: &[T], mut f: F) -> Vec<U> {
    xs.iter().map(|x| f(x)).collect()
}

/// `filter(list, keep)`: the kept elements, cloned into an owned result.
pub fn salvo_filter<T: Clone, F: FnMut(&T) -> bool>(xs: &[T], mut keep: F) -> Vec<T> {
    xs.iter().filter(|x| keep(x)).cloned().collect()
}

/// `reduce(list, init, f)`: a fold whose accumulator is *borrowed* by the
/// callback, which is why this is not `Iterator::fold` (that passes it by
/// value).
pub fn salvo_reduce<T, A, F: FnMut(&A, &T) -> A>(xs: &[T], init: A, mut f: F) -> A {
    let mut acc = init;
    for x in xs.iter() {
        acc = f(&acc, x);
    }
    acc
}

/// [linear-container] [rs-borrows] Take-by-move out of a list, as **methods**
/// rather than an inline `&mut` block: a `Mut List<T>` parameter is already a
/// `&mut Vec<T>` and cannot be re-borrowed by an inline `&mut` (it is not a
/// `mut` binding), while method syntax auto-refs an owned local and re-borrows
/// a reference alike — and splices the receiver exactly once, which an
/// `if is_empty() … remove(0)` expression cannot.
pub trait SalvoTake<T> {
    /// `remove_first(list)`: the first element, moved out.
    fn salvo_remove_first(&mut self) -> Option<T>;
    /// `remove_at(list, i)`: the element at `i`, moved out.
    fn salvo_remove_at(&mut self, index: i32) -> Option<T>;
}

impl<T> SalvoTake<T> for Vec<T> {
    fn salvo_remove_first(&mut self) -> Option<T> {
        if self.is_empty() {
            None
        } else {
            Some(self.remove(0))
        }
    }

    fn salvo_remove_at(&mut self, index: i32) -> Option<T> {
        if index < 0 {
            return None;
        }
        let index = index as usize;
        if index < self.len() {
            Some(self.remove(index))
        } else {
            None
        }
    }
}

/// [rs-elem-mut] Two `&mut` elements of one `Vec` at once — the rendering
/// of a call taking two mutable element handles the checker proved apart
/// (`Distinct`, [elem-distinct]): one `split_at_mut` at the higher index,
/// one element out of each half. `i != j` is checker-guaranteed; `None`
/// when either index is out of range, so the caller's `.expect` carries
/// the same message and timing as a single handle's `!`.
pub fn salvo_pair_mut<T>(xs: &mut [T], i: usize, j: usize) -> Option<(&mut T, &mut T)> {
    if i == j || i >= xs.len() || j >= xs.len() {
        return None;
    }
    if i < j {
        let (lo, hi) = xs.split_at_mut(j);
        Some((&mut lo[i], &mut hi[0]))
    } else {
        let (lo, hi) = xs.split_at_mut(i);
        Some((&mut hi[0], &mut lo[j]))
    }
}
